mapper.select:
SELECT DISTINCT
    O.*
FROM ORDERS O
WHERE O.ORDER_STATUS = 1
  AND O.MEMBER_NO = #{memberNo}
  AND O.PRODUCT_TYPE IN (1, 2, 5)
  AND (
    EXISTS (
        SELECT 1 FROM ORDER_SERVER S
        WHERE S.ORDER_NO = O.ORDER_NO
          AND S.SERVER_ID = #{serverId}
    )
    OR O.ORDER_NO IN (
        SELECT BV.ORDER_NO FROM BUSINESS_VHOST BV
        WHERE BV.ID = #{serverId}
          AND (BV.DELETE_FLAG IS NULL OR BV.DELETE_FLAG = 'NOT_DELETE')
          AND BV.ORDER_NO IS NOT NULL
    )
    OR O.ORDER_NO IN (
        SELECT BV.LAST_ORDER_NO FROM BUSINESS_VHOST BV
        WHERE BV.ID = #{serverId}
          AND (BV.DELETE_FLAG IS NULL OR BV.DELETE_FLAG = 'NOT_DELETE')
          AND BV.LAST_ORDER_NO IS NOT NULL
    )
    OR EXISTS (
        SELECT 1 FROM vhost_order_config C
        WHERE C.ORDER_NO = O.ORDER_NO
          AND C.HOST_ID = #{serverId}
    )
  )
